            raise StoreError(f"cannot persist data file {self.path}: {exc}") from exc

    def _prune_locked(self) -> bool:
        now = time.time()
        expired = [
            key for key, entry in self.entries.items() if self._is_expired(entry, now)
        ]
        for key in expired:
            del self.entries[key]
